<?php
namespace App\Http\Controllers;use App\Models\{TransportStop,Vehicle,VehicleLocation};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class TransportTrackingController extends Controller{public function ingest(Request $r,Vehicle $vehicle){abort_unless($vehicle->tracking_token_hash&&hash_equals($vehicle->tracking_token_hash,hash('sha256',(string)$r->bearerToken())),401);$d=$r->validate(['latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','speed'=>'nullable|numeric|min:0','heading'=>'nullable|numeric|between:0,360','recorded_at'=>'nullable|date']);VehicleLocation::create($d+['vehicle_id'=>$vehicle->id,'recorded_at'=>$d['recorded_at']??now()]);if($vehicle->transport_route_id)foreach(TransportStop::where('transport_route_id',$vehicle->transport_route_id)->whereNotNull('latitude')->get() as $stop){$distance=$this->distance($d['latitude'],$d['longitude'],$stop->latitude,$stop->longitude);if($distance<=$stop->geofence_radius_m&&!DB::table('transport_geofence_events')->where('vehicle_id',$vehicle->id)->where('transport_stop_id',$stop->id)->where('event_at','>=',now()->subMinutes(15))->exists())DB::table('transport_geofence_events')->insert(['vehicle_id'=>$vehicle->id,'transport_stop_id'=>$stop->id,'event'=>'arrived','event_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}return response()->json(['accepted'=>true]);}private function distance($a,$b,$c,$d){$r=6371000;$x=deg2rad($c-$a);$y=deg2rad($d-$b);$z=sin($x/2)**2+cos(deg2rad($a))*cos(deg2rad($c))*sin($y/2)**2;return $r*2*atan2(sqrt($z),sqrt(1-$z));}}
